session_start();if(empty($_SESSION['utilisateur_id'])){header('Location: ../connexion.php');exit;}$roles=$_SESSION['utilisateur_roles']??[];if(!is_array($roles)||!in_array('administrateur',$roles,true)){http_response_code(403);exit('Accès refusé.');}
require_once __DIR__.'/../classes/Database.php';$pdo=(new Database())->getConnection();if(empty($_SESSION['csrf_paiement_admin']))$_SESSION['csrf_paiement_admin']=bin2hex(random_bytes(32));
$stmt=$pdo->query("SELECT pa.*,a.id_proprietaire,u.nom,u.telephone FROM paiement_abonnement pa INNER JOIN abonnement a ON a.id_abonnement=pa.id_abonnement INNER JOIN utilisateur u ON u.id_utilisateur=a.id_proprietaire ORDER BY CASE pa.statut_paiement WHEN 'en_attente' THEN 0 ELSE 1 END,pa.date_paiement DESC");$paiements=$stmt->fetchAll(PDO::FETCH_ASSOC);function h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?>
<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Paiements | MIGON</title><link rel="stylesheet" href="../public/css/style.css"><style>.page{max-width:1100px;margin:35px auto;padding:20px}.card{background:#fff;border:1px solid #e2e8e4;border-radius:12px;padding:20px}.table{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:850px}th,td{padding:12px;border-bottom:1px solid #e5e9e7;text-align:left}th{background:#f4f8f5}.btn{background:#123b32;color:#fff;border:0;border-radius:7px;padding:9px 12px;cursor:pointer}.btn.refus{background:#b42318}.motif{width:100%;padding:8px;margin-top:6px}.ok{background:#e7f5ee;padding:10px}.ko{background:#fff1f0;padding:10px}</style></head><body><main class="page"><p><a href="index.php">← Administration</a></p><h1>Validation des paiements</h1><?php if(isset($_GET['resultat'])):?><p class="ok">Le paiement a été traité.</p><?php endif;?><section class="card"><div class="table"><table><thead><tr><th>Propriétaire</th><th>Abonnement</th><th>Paiement</th><th>Référence</th><th>Statut</th><th>Action</th></tr></thead><tbody><?php foreach($paiements as $p):?><tr><td><?=h($p['nom'])?><br><small><?=h($p['telephone'])?></small></td><td>#<?= (int)$p['id_abonnement'] ?><br>2 000 XOF</td><td><?=h($p['methode_paiement'])?><br><small><?=h($p['date_paiement'])?></small></td><td><?=h($p['reference_paiement']?:'—')?></td><td><?=h($p['statut_paiement'])?></td><td><?php if($p['statut_paiement']==='en_attente'):?><form method="post" action="traitement-paiement.php"><input type="hidden" name="csrf_token" value="<?=h($_SESSION['csrf_paiement_admin'])?>"><input type="hidden" name="id_paiement" value="<?= (int)$p['id_paiement'] ?>"><button class="btn" name="action" value="confirmer">Confirmer</button><br><input class="motif" name="commentaire" maxlength="5000" placeholder="Motif en cas de refus"><button class="btn refus" name="action" value="refuser" style="margin-top:6px">Refuser</button></form><?php else:?><small>Traité le <?=h($p['date_validation']??'')?></small><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>
